  @Override
  public Epoch awaitInitialized() throws InterruptedException {
    if (this.initialized) {
      return this.epoch;
    }
    lock.lock();
    try {
      while (!this.initialized) {
        initializedCondition.await();
      }
      return this.epoch;
    } finally {
      lock.unlock();
    }
  }
